import { disabled, fieldSurface, focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const input = tv({
  base: [
    "w-full min-w-0",
    fieldSurface,
    "file:mr-3 file:border-0 file:bg-transparent file:font-display file:font-bold file:uppercase",
    "read-only:shadow-none",
    focusRing,
    disabled,
  ],
  variants: {
    size: {
      sm: "h-11 px-2.5 text-sm",
      md: "h-12 px-3 text-base",
      lg: "h-14 px-4 text-lg",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type InputVariants = VariantProps<typeof input>;

"use client";

import { Input as BaseInput } from "@base-ui/react/input";
import { input, type InputVariants } from "@/lib/beton/recipes/input.recipe";

export interface InputProps extends Omit<BaseInput.Props, "className" | "size">, InputVariants {
  className?: string;
  /** Native `size` attribute (visible width in characters). Use `size` for the visual size. */
  htmlSize?: number;
}

export function Input({ size = "md", htmlSize, className, ...props }: InputProps) {
  return (
    <BaseInput
      {...props}
      size={htmlSize}
      data-size={size}
      className={input({ size, class: className })}
    />
  );
}
